from lesson_helpers import *
from lesson_figures import figure,CSS
T=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-N06"><div class="chap"><div class="chap-head"><div class="code">N06 · N-07-Néphrologie</div><h1>Protéinurie isolée avec lésions morphologiques précisées</h1><span class="status">Monographie pédagogique · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#n06-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(T,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="N06">'''
a+=sec('question','Des protéines dans l’urine, sans plainte : que faut-il vérifier ?', '''<p><b>Vignette fictive.</b> Une personne se sent en bonne santé. Une bandelette faite après une course montre des protéines ; un autre dossier mentionne une protéinurie persistante et une lésion segmentaire sur une ancienne biopsie. Ces observations appellent-elles la même décision ? Le mot « protéinurie » ne précise ni quantité, ni composition, ni durée, et une lésion ancienne ne dit pas tout de son activité actuelle.</p><p>Il faut confirmer une anomalie mesurée correctement, vérifier qu’elle est réellement isolée, puis établir son mécanisme et son risque. Une protéinurie transitoire après effort, une perte tubulaire de petites protéines et une atteinte glomérulaire ne se traitent pas de la même manière. Une absence de symptômes n’écarte pas une maladie.</p>'''+key('Commencer par la mesure, puis relier quantité, composition, persistance et contexte à une décision.'),('CH-PROT-METHOD','EU-PROT-WORKUP','CH-PROT-MEC'))
a+=sec(1,'1. Définition : un signe urinaire, puis une lésion à préciser', '''<p>La protéinurie est l’excrétion de protéines dans l’urine. L’adulte sain en excrète une petite quantité ; les références retenues situent la limite physiologique autour de150mg/j. L’albumine n’est qu’une partie de ces protéines : son excrétion habituelle est inférieure à30mg/j. Une anomalie peut porter sur la quantité et sur la nature des protéines.</p><p>Une présentation dite <b>isolée</b> signifie que la découverte de protéines n’est pas accompagnée d’un autre tableau rénal évident. Ce caractère doit être vérifié : pression, sédiment, fonction, albumine sanguine et examen clinique recherchent ce qui pourrait modifier cette qualification. Une personne asymptomatique peut avoir une albuminurie pathologique persistante et une maladie rénale avec filtration conservée.</p><p>L’intitulé suisseN06 ajoute une condition : <b>des lésions morphologiques précisées</b>. Une protéinurie isolée sans autre indication n’est pas automatiquementN06. La nomenclature distingue notammentR80 pour protéinurieSAI/isoléeSAI ou deBenceJones,N39.1 pour persistanteSAI,N39.2 pour orthostatiqueSAI etO12.1 pour gestationnelle. Le diagnostic clinique et la documentation du tissu précèdent le choix du code.</p><p>Une morphologie ne nomme pas toujours la cause. Segmentaire, focale, membranoproliférative ou autre décrit une lésion ou une distribution ; il faut encore comprendre son mécanisme, son activité et sa conséquence pour le patient.</p>''',('CH-PROT-METHOD','EU-PROT-DEF','INT-CKD-DEF','CH-CIM','EU-HISTO'))
a+=sec(2,'2. Épidémiologie : distinguer dépistage, maladie et code', '''<p>Aucune incidence suisse directeN06 n’a été retenue dans les sources consultées. Le nombre de bandelettes positives dépend de l’âge, du dépistage, des circonstances de recueil et de la confirmation. Une première positivité n’a pas la même signification qu’une protéinurie persistante avec une lésion biopsique.</p><p>Le guideSGN2025 estime qu’environ un adulte sur dix enSuisse présente une maladie rénale chronique. Ce chiffre ne mesure ni la protéinurie isolée niN06. Les séries de biopsies décrivent des personnes sélectionnées pour cet examen ; elles ne représentent pas toutes les anomalies urinaires de la population.</p><p>Le CUEN décrit la protéinurie orthostatique surtout à la période pubertaire. Cette orientation d’âge aide à choisir un prélèvement ; elle ne permet pas de conclure à la bénignité d’une protéinurie persistante chez un jeune sans vérifier le profil. Les maladies associées, le terrain familial, les médicaments et la trajectoire changent la probabilité des causes. Aucune fréquence individuelle d’un signe n’est inventée.</p>''',('CH-SGN-DEF','EU-PROT-WORKUP','CH-PROT-REF'))
a+=sec(3,'3. Physiopathologie : filtre, réabsorption et surcharge', '''<p>Le filtre glomérulaire associe endothélium, membrane basale et podocytes. Il limite le passage des cellules et de nombreuses protéines ; le tubule proximal récupère une grande partie des protéines filtrées. L’urine finale contient aussi des protéines sécrétées, notamment l’uromoduline. Une excrétion physiologique ne correspond donc pas à une fuite pathologique d’albumine.</p>'''+figure('podocytes')+'''<p>Une atteinte glomérulaire augmente le passage de protéines plasmatiques, souvent à prédominance albuminurique. Une atteinte tubulaire diminue la réabsorption de protéines de faible poids moléculaire. Une protéinurie de surcharge apparaît lorsque des protéines circulantes abondantes dépassent les capacités de réabsorption, par exemple des chaînes légères d’immunoglobulines ou de la myoglobine. Ces mécanismes peuvent se combiner ; la présence d’albumine n’exclut pas toute participation tubulaire.</p><p>La composition donne ainsi une information que la bandelette ou le total ne fournissent pas seuls. Une protéinurie peut aussi être transitoire dans un contexte d’effort, de fièvre ou de variation hémodynamique. La confirmation et les anomalies associées évitent de confondre cette situation avec une maladie persistante.</p><p>Les protéines filtrées en excès peuvent participer à une réponse tubulo-interstitielle inflammatoire et à la fibrose ; elles sont aussi un marqueur de lésion et de risque. Diminuer une protéinurie ne prouve toutefois pas que toute cause ou toute cicatrice ait disparu. L’originalPAS ci-dessous montre une lésion attribuée par sa provenance à une variante hilaire de sclérose segmentaire et focale ; il n’établit ni cause primitive ni indication de corticoïdes.</p>'''+figure('fsgs'),('NORMAL-FILTRE','CH-PROT-MEC','EU-PROT-DEF','EU-HISTO','INT-GN-GENERAL'))
a+=sec(4,'4. Démarche clinique : confirmer sans perdre les signes d’alerte', '''<p><b>Vérifier la gravité.</b> Une dyspnée, une oligurie, une dégradation rapide de fonction, une hypertension avec retentissement ou des signes systémiques sortent du simple constat isolé. Un sédiment néphritique associé à une perte rapide de fonction impose un bilan accéléré. La répétition d’un prélèvement ne doit pas retarder cette démarche.</p><p><b>Confirmer la mesure.</b> Préciser produit de bandelette, recueil, effort, fièvre, infection, menstruations et contamination. Confirmer une positivité semi-quantitative par une mesure de laboratoire exprimée en rapport à la créatinine, avec analyte et unité visibles. Le premier prélèvement du matin à mi-jet est préféré pour comparer et confirmer.</p><p><b>Caractériser.</b> Confronter albumine et protéines totales, sédiment, pression et fonction rénale. Rechercher une dépendance posturale lorsque le contexte s’y prête ; ne pas appeler orthostatique toute protéinurie d’un adolescent. La persistance doit être documentée sur des contrôles appropriés.</p><p><b>Établir cause et plan.</b> Examiner le terrain, les examens antérieurs et l’éventuel compte rendu de biopsie. Le néphrologue choisit les investigations susceptibles de changer le traitement. Le suivi doit préciser qui contrôle, à quel délai et quels signes nécessitent un contact anticipé.</p>''',('CH-PROT-REF','INT-CKD-URINE','EU-PROT-WORKUP','CH-SGN-REF','INT-GN-GENERAL'))
a+=sec(5,'5. Anamnèse : expliquer le résultat avant de nommer la maladie',table(['Domaine','Questions','Conséquence'],[['Recueil','Heure, posture, effort, fièvre, menstruations, infection, qualité de collecte','Chercher une variation transitoire ou une contamination.'],['Chronologie','Résultats normaux ou anormaux datés, répétitions, ancienne biopsie','Prouver persistance et évolution ; ne pas supposer une durée.'],['Signes urinaires','Sang visible, dysurie, diurèse, urine mousseuse','La mousse ne quantifie pas ; sang et symptômes réorientent le bilan.'],['Retentissement','Œdèmes, poids, dyspnée, symptômes tensionnels','Vérifier que la présentation soit encore isolée.'],['Terrain','Diabète, hypertension, maladie systémique, infection ou gammapathie connue','Orienter la cause sans attribution automatique.'],['Famille','Protéinurie, hématurie, insuffisance rénale, audition et yeux','Discuter une maladie génétique et une atteinte associée.'],['Médicaments','AINS, traitements récents, produits naturels, compléments et observance','Chercher toxicité, interaction et modification fonctionnelle.'],['Population','Croissance, grossesse/projet, fragilité, masse musculaire, alimentation','Adapter références, estimation et sécurité des traitements.']])+'''<p>Le patient peut ne ressentir aucun symptôme. L’anamnèse ne consiste donc pas seulement à rechercher une plainte : elle restitue les conditions de mesure et la trajectoire. Une ancienne mention de « lésion minime » ou « sclérose » demande le compte rendu exact, sa date et les techniques utilisées ; une mémoire résumée ne remplace pas le tissu documenté.</p>''',('EU-PROT-WORKUP','INT-CKD-URINE','INT-CKD-DRUG','EU-ALPORT-GEN','EU-HISTO'))
a+=sec(6,'6. Examen clinique : éprouver le caractère isolé', '''<p>Mesurer la pression avec une méthode reproductible, rechercher œdèmes, variations pondérales, congestion et état d’hydratation. Une fonction dite normale dans le dossier ne dispense pas d’une mesure actuelle. Les signes de maladie systémique sont recherchés selon l’histoire : peau, articulations, manifestations infectieuses, respiratoires ou autres.</p><p>La présence d’une hypertension, d’une hématurie, d’une baisse de fonction ou d’une hypoalbuminémie change la synthèse. Il faut alors qualifier le syndrome réellement présent plutôt que maintenir « isolée » par habitude. Une absence d’œdèmes n’exclut ni une perte protéique importante ni une maladie rénale débutante.</p><p>Chez l’enfant, croissance et pression demandent des références pédiatriques. Chez la personne âgée ou sarcopénique, masse musculaire, nutrition et fragilité influencent l’interprétation de la créatinine et des rapports urinaires. L’examen vérifie également la tolérance des traitements déjà pris.</p><p>Une cible tensionnelle est un objectif thérapeutique dans un cadre défini, non un critère de N06. Si une MRC est établie, laSGN2025 propose une systolique120–129mmHg individualisée ; la différence avecKDIGO&lt;120 en mesure standardisée est attribuée. Aucun antihypertenseur n’est choisi sur le seul nom du code.</p>''',('CH-SGN-PEC','EU-PROT-WORKUP','INT-CKD-URINE','INT-CKD-DRUG','INT-CKD-TX'))
a+=sec(7,'7. Syndromes et classifications : ne pas mélanger les seuils',table(['Dimension','Repères','Limite'],[['Protéines physiologiques','Adulte : environ100–150mg/j','Toutes les protéines ne sont pas de l’albumine.'],['Albuminurie','A1<30,A2 30–300,A3>300mg/g ; bornes approximatives3/30mg/mmol','Un rapport n’est pas une collecte24hmesurée.'],['Protéinurie clinique','CUEN :>500mg/j ou>500mg/g comme repère','Différent de la limite physiologique150mg/j.'],['Persistance/posture','Transitoire,orthostatique ou permanente','À démontrer ; âge ou absence de plainte insuffisants.'],['Syndrome néphrotique','CUENadulte :protéines>3g/j oug/g etalbumine<30g/L','Thurgau utilise3,5g/j pourprotéinurienéphrotique ; référentiels attribués.'],['MRC','Anomalie≥3mois ; cause,categorieG etalbuminurieA','G1/G2 sans marqueur de dommage ne suffisent pas.'],['Morphologie','Distribution,lésion,dépôts,activité etfibrose','Pas une étiologie ou une prescription complète.']])+'''<p>Les catégories de débit de la MRC sontG1≥90,G2 60–89,G3a45–59,G3b30–44,G4 15–29 etG5&lt;15mL/min/1,73m². Elles s’interprètent avec marqueurs et durée. Une albuminurie pathologique persistante peut établir une maladie avec un débitG1 ; l’absence de baisse de fonction ne prouve pas l’absence de dommage.</p><p>Le débit de protéines, leur composition et l’albuminémie décrivent encore des informations distinctes. Les seuils de consultation ou de biopsie ne sont pas automatiquement les mêmes que les seuils définissant normalité, catégorie de risque ou syndrome néphrotique.</p>''',('CH-PROT-METHOD','EU-PROT-DEF','EU-PROT-WORKUP','INT-CKD-DEF','EU-HISTO'))
save('a',a)
b=sec(8,'8. Diagnostic positif : cinq questions de preuve', '''<p><b>Le résultat est-il réel ?</b> Confirmer une bandelette par une mesure quantitative ; vérifier dilution, recueil et facteurs transitoires. Une bandelette négative peut manquer une albuminurie modérée ou une protéinurie non albuminurique. Une valeur de concentration seule dépend de la dilution.</p><p><b>Quelle composition ?</b> L’ACR mesure l’albumine et lePCR les protéines totales. Un total élevé avec peu d’albumine fait rechercher notamment une composante tubulaire ou de surcharge, selon le contexte et les examens adaptés. Il ne faut ni banaliser cette discordance ni la nommer automatiquement glomérulaire.</p><p><b>Quelle durée et quelle posture ?</b> Confirmer au premier matin et sur contrôles comparables. Dans un contexte pubertaire compatible, une disparition après décubitus avec absence d’autres anomalies soutient une protéinurie orthostatique ; le protocole et la concordance clinique sont vérifiés. Une anomalie permanente demande une recherche de cause.</p><p><b>Est-elle isolée ?</b> Vérifier pression, sédiment, fonction, albumine et manifestations systémiques. Une albuminurie persistante peut constituer un marqueur de MRC même avec filtration conservée. L’intervalle de trois mois ne justifie aucune attente en cas de signes d’alerte.</p><p><b>Quelle morphologie est prouvée ?</b> N06 ne se déduit pas du seul dosage. Reprendre la biopsie lorsqu’elle existe et discuter sa nécessité pour une décision clinique, sans geste invasif destiné au codage. Cause et activité restent à interpréter avec le dossier.</p>''',('INT-CKD-URINE','CH-PROT-METHOD','CH-PROT-MEC','EU-PROT-WORKUP','INT-CKD-DEF','CH-CIM','INT-GN-GENERAL'))
b+=sec(9,'9. Explorations : de la mesure au tissu',table(['Outil','Question','Limite'],[['ACR etPCR','Quantité et fractionalbumine ?','Prélèvement et excrétion decréatinine variables ; unités indispensables.'],['Sédiment/ECBU selon contexte','Hématurie,cellules,cylindres,infection ?','Un autreprofil peut invalider le caractèreisolé.'],['Créatinine/débit,albumine,biologie orientée','Fonction,syndrome,retentissement ou cause ?','Valeur unique ne prouve durée oumécanisme.'],['Électrophorèse/immunofixation selonhypothèse','Petitesprotéines ou composantmonoclonal ?','Indication etinterprétation guidées parcontexte, pas parBU seule.'],['Échographie','Structure,taille,voiesurinaires ?','Ne montre pas dépôts oupédicelles.'],['Immunologie,génétique','Causeimmune,familiale oustructurale plausible ?','Positivité isolée et variantincertain ne donnent pas toutdiagnostic.'],['Biopsie','Étiologie,activité,chronicité et changement depriseencharge ?','Échantillon limité,risques et techniquescomplémentaires.']])+'''<p>Le néphrologue confronte le débit protéique, les anomalies associées et le bénéfice attendu du prélèvement. Les principes glomérulairesKDIGO recommandent une quantification précise, parfois24h chez l’adulte lorsqu’une décision d’immunosuppression en dépend. Le recueil24h n’est donc ni obligatoire pour toute découverte ni inutile dans toutes les situations.</p><p>Optique, immunofluorescence et électronique interrogent des dimensions différentes. Un aspectFSGS peut être primaire, secondaire ou associé à une maladie génétique. Une photographie ou une ligne du compte rendu ne décide pas seule d’une immunosuppression. Une hypothèseIgA possède aussi ses propres critères de discussion biopsique ; elle ne transforme pas un seuil en règle universelle de toute protéinurie.</p>''',('CH-PROT-METHOD','CH-PROT-MEC','EU-PROT-WORKUP','INT-GN-GENERAL','EU-HISTO','EU-ALPORT-GEN','INT-IGA-DX'))
b+=sec(10,'10. Arbre diagnostique et diagnostics différentiels',table(['Étape','Observation','Décision'],[['1. Gravité/anomaliesassociées','Retentissement,fonctionrapide,sédimentnéphritique','Bilanaccéléré ; requalifier lesyndrome.'],['2. Confirmation','Mesurequantitative,unité,premiermatin,conditions','Écartererreur,contamination et facteurtransitoire.'],['3. Posture/persistance','Normalisationendécubitus ouanomaliepermanente','Protocoleadapté ; éviterbiopsie d’uneorthostatique confirméeconcordante.'],['4. Composition','Albuminemajoritaire oudiscordanceACR/RPC','Chercherorigineglomérulaire,tubulaire oudesurcharge.'],['5. Cause/risque','Terrain,famille,maladiesassociées,tissu','Investigationsorientées,avisnéphrologique etplan.']])+'''<p>Une protéinurie tubulaire ou de surcharge peut être discrète à la bandelette. Une maladie systémique, une gammapathie, une atteinte médicamenteuse ou une maladie héréditaire fait partie des alternatives orientées par le dossier. Le diagnostic ne se réduit pas à « albumine absente, donc pas de problème ».</p><p>Les anomalies nouvelles chez une personne déjà biopsiée ne sont pas forcément la simple poursuite de la lésion ancienne. Une infection, une modification hémodynamique ou une maladie associée peut changer l’évolution. La discordance entre profil attendu et données actuelles justifie une reprise du raisonnement.</p>''',('CH-PROT-REF','CH-PROT-MEC','EU-PROT-WORKUP','INT-CKD-URINE','EU-ALPORT-GEN','INT-CKD-DRUG'))
b+=sec(11,'11. Prise en charge : traiter une cause et un risque établis', '''<p><b>Pas de prescription sur la seule bandelette.</b> Une protéinurie transitoire se réévalue après disparition du facteur déclenchant. Une orthostatique confirmée avec un profil concordant n’appelle pas automatiquement une biopsie ou une immunosuppression. Une protéinurie permanente ou une anomalie associée demande une démarche de cause et de risque.</p><p><b>Orientation spécialisée.</b> La fiche suisseThurgau propose notamment une exploration néphrologique devant albuminuriepersistante&gt;300mg/j ou protéines&gt;0,5–1g/j ; leCUEN retient un avis devant protéinurie permanente&gt;0,5g/j. LaSGN2025 ajoute cause inconnue, hématurieglomérulaire, progression et autres critèresMRC. Il s’agit de repères de consultation, pas de seuils automatiques de biopsie. Une dégradation rapide ou un retentissement grave accélère les soins.</p><p><b>Traitement de cause.</b> La maladie démontrée, l’activité et les dommages orientent une éventuelle intervention spécifique. Une sclérose ne se confond pas avec une inflammation ; une infection et une maladie immune n’appellent pas la même stratégie. Aucun corticoïde universel n’est indiqué par le seulN06.</p><p><b>Néphroprotection lorsque indiquée.</b> Dans une MRC établie, considérer cause, albuminurie, filtration, pression et tolérance. IEC/ARA et éventueliSGLT2 suivent les recommandations et lesFI exactes, dont les indications et restrictions diffèrent. La recommandation de classe dèsDFG20 ne modifie pas l’introductionForxiga nonrecommandée sous25. RevoirAINS, interactions, grossesse et risque de déplétion ; toute pause comporte un plan de contrôle et de reprise.</p><p>Une pression normale et l’absence d’œdèmes n’imposent pas amlodipine ou furosémide. Si ces signes apparaissent et justifient leur emploi, il faut réviser la qualification de la présentation et traiter leur mécanisme. Les schémas du voletpharmacologique sont conditionnels, jamais une ordonnance deN06.</p>''',('EU-PROT-WORKUP','CH-PROT-REF','CH-SGN-REF','CH-SGN-PEC','INT-CKD-TX','FI-RAMIPRIL','FI-COSAAR','FI-FORXIGA','FI-NORVASC','FI-LASIX-PO','EU-HISTO'))
b+=sec(12,'12. Prévention, suivi et pronostic : suivre une trajectoire', '''<p>Le suivi vérifie la persistance, l’évolution de la quantité et de la composition, la pression, la fonction et l’apparition d’autres signes. Comparer des prélèvements réalisés dans des conditions cohérentes, avec le même analyte et les unités visibles. Une normalisation isolée peut refléter un changement de dilution ou de contexte ; elle se confronte aux autres données.</p><p>Le risque dépend de la cause, des lésions, de la fonction, de l’albuminurie et de leur trajectoire. Une morphologie ne donne pas un pronostic individuel certain. Dans la MRC, contrôler débit et albuminurie au moins annuellement, plus souvent selon risque ou changement de traitement. Une variationDFG&gt;20%, une baisse&gt;30% après thérapie hémodynamique ou un doublementACR appelle une évaluation ; ces repères ne remplacent pas les soins d’une aggravation symptomatique.</p><p>Les équations validées de risque rénal s’utilisent dans leur population, principalementG3–G5 ; ne pas les extrapoler automatiquement àG1/G2 ou à une fonction instable. La prévention associe revue des médicaments, mode de vie adapté et organisation des contrôles. Les recommandations alimentaires d’adulteMRC ne se transposent pas automatiquement à l’enfant ou à la personne fragile.</p><p>Expliquer au patient la signification des mesures, le prochain rendez-vous et les signes de contact anticipé : baisse de diurèse, dyspnée, œdèmes nouveaux, sang visible ou altération générale selon le contexte. Le suivi doit rester proportionné et compréhensible.</p>''',('INT-CKD-URINE','INT-CKD-RISK','INT-CKD-TX','INT-CKD-DRUG','CH-SGN-REF','EU-HISTO'))
b+=sec(13,'13. Points clés pour l’examen fédéral', '''<p>Décrire une protéinurie par quantité, composition, persistance et contexte ; vérifier fonction, pression et sédiment avant de la dire isolée. Expliquer pourquoi l’ACR et lePCR répondent à des questions différentes, pourquoi le premier matin est utile et pourquoi une bandelette négative ne ferme pas toutes les causes.</p><p>DansPROFILES2017, la tâche173 concerne la protéinurie,161 la fonction,164 le sédiment et159 les investigations tissulaires/génétiques. Les directivesMEBEKO2026 relient connaissances et compétences cliniques. Les cas et quiz ci-dessous sont originauxMEDINA, sans statut de questions officielles.</p><p>Une synthèse utile relie le résultat confirmé, le mécanisme probable, le risque et le plan. Le code et la morphologie apparaissent après cette conclusion ; ils ne remplacent pas une explication au patient.</p><p>'''+''.join(w('cas-'+str(i),'Cas clinique '+str(i))+' ' for i in range(1,5))+'''</p>''',('CH-PROFILES','CH-MEBEKO','CH-PROT-METHOD','EU-PROT-WORKUP'))
b+=sec(14,'14. Pièges : protéger la mesure et le raisonnement',table(['Raccourci','Correction','Conséquence'],[['Bandelettenégative=toutnormal','Sensibilité àl’albumine et protéinesnonalbuminiques limitée','Quantifier selon question et contexte.'],['Concentration=pertequotidienne','La dilution modifie g/L','Rapportavecunité oucollecte adaptée.'],['×10=conversionexacte','Estimationavec excrétioncréatinine présumée','Ne pasannoncer une collecte24hmesurée.'],['Albumine=protéinestotales','Analytesdifférents','ConfronterACR/RPC etqualifierlesdiscordances.'],['Adolescent=orthostatique','Postureetprofil àdémontrer','Pasdeconclusion surl’âgeseul.'],['Isolée=sansrisque','Marqueurpersistant peutétablirMRCavecG1','Recherchercause etorganisersurveillance.'],['FSGS=causeprimitive','Patternavecplusieursmécanismes','Pasdecorticoïdes surimage/code.'],['Touteprotéinurie=N06','MorphologieetexclusionsOFS comptent','Pasdebiopsieadministrative.'],['Baisseprotéines=guérison','Marqueur,activité etcicatrices distincts','Suivrefonction,clinique etcause.']])+key('La bonne mesure précise le signe ; le contexte lui donne sa signification.'),('INT-CKD-URINE','CH-PROT-METHOD','CH-PROT-MEC','EU-PROT-WORKUP','EU-HISTO','CH-CIM'))
b+='</div></div>';save('b',b)
